  "prediction_basis_card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07", "C19"],
  "claims": [
    {
      "claim": "Direct human absolute/relative F records for nucleoside analogs in the gold contexts are at or above the 20% threshold: zalcitabine absolute F ≈80% (range 54–127%) in fasted patients and 70–90% in broader studies; didanosine fasted F was 22–29%; zidovudine F was 0.61 in patients with cirrhosis.",
      "card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07"]
    },
    {
      "claim": "L6 hepatic-clearance records are for other molecules: GS-441524 is not a substrate of major CYP isoforms, zidovudine HLM glucuronidation CLint values are low (0.73–3.79 µL/min/mg), and dapagliflozin CYP oxidation is <10%; none measure AICAR hepatic clearance or metabolic stability, so they do not affirmatively establish F < 20%.",
      "card_ids": ["C77", "C80", "C71", "C72", "C73", "C74", "C75", "C76", "C78", "C79", "C82", "C81"]
    },
    {
      "claim": "Low Caco-2/PAMPA permeability records for other nucleosides (ribavirin, levovirin, gemcitabine, GS-441524) are mechanistic analog evidence with low transferability and may under-predict transporter-mediated nucleoside absorption; they are insufficient to override direct human F records.",
      "card_ids": ["C52", "C50", "C51", "C56"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78", "C79", "C80", "C81", "C82"]
    }
  ],
  "evidence_gaps": [
    "No AICAR-specific absolute oral bioavailability or systemic exposure measurement is supplied.",
    "No AICAR-specific hepatic clearance or metabolic-stability data are supplied; L6 records are for GS-441524, zidovudine, and dapagliflozin.",
    "No AICAR-specific intestinal permeability, gut-wall efflux, or intestinal metabolism data are supplied.",
    "No formulation, dose, prandial state, or species context for AICAR is supplied.",
    "Whether AICAR is a substrate of uptake/efflux transporters or undergoes significant first-pass metabolism is uncharacterized.",
    "Caco-2/PAMPA low permeability may under-predict transporter-mediated nucleoside absorption, as noted for ribavirin and hCNT2."
  ],
  "decision_summary": "Prediction remains high: direct human nucleoside-analog F records support F ≥ 20%, and L6 hepatic-clearance records are non-AICAR mechanistic analogs that do not affirmatively establish F < 20%. Confidence remains low due to lack of AICAR-specific PK and low-permeability analog concerns."
}

